from __future__ import annotations

from api.operator_console_runner_preview import CONSOLE_HTML_V38

RUNNER_CONTROL_SCRIPT = r"""
<style>
.runner-control{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.run-warning{padding:12px;border:1px solid #f2c6c2;background:#fff5f4;border-radius:10px;color:#8f2118;margin-bottom:10px}.run-confirm{display:flex;gap:9px;align-items:flex-start;padding:12px;border:1px solid #e2edf8;background:#fbfdff;border-radius:10px}.run-button{width:100%;margin-top:10px;border:0;border-radius:10px;padding:13px;background:#8f2118;color:#fff;font-weight:900;cursor:pointer}.run-button:disabled{opacity:.5;cursor:not-allowed}.run-status{min-height:20px;margin-top:10px;font-size:13px}.run-status.ok{color:#147a46}.run-status.err{color:#b42318}.receipt-box{margin-top:10px;border:1px solid #dce9f8;border-radius:12px;padding:12px;background:#fbfdff;font-size:13px;overflow-wrap:anywhere}
</style>
<script>
async function loadRunnerControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('runner-control');if(!box){box=document.createElement('section');box.id='runner-control';box.className='runner-control';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Execute One Read-Only Call</h3><div class="muted">Checking final preflight…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/runner-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.detail||'runner context unavailable')}const d=await r.json();if(!d.ready){box.innerHTML=`<h3>Execute One Read-Only Call</h3><div class="muted">Not available: ${esc((d.reason||'not ready').replaceAll('_',' '))}</div>`;return}const p=d.dispatch_plan;box.innerHTML=`<h3>Execute One Read-Only Call</h3><div class="run-warning"><strong>This is the execution boundary.</strong> Confirming below will consume ticket ${esc(d.dispatch_ticket_id)} and perform exactly one internal read-only call: <strong>${esc(p.capability_id)} / ${esc(p.operation)}</strong>. The ticket is claimed before the upstream call and remains consumed even if the read fails.</div><label class="run-confirm"><input type="checkbox" id="run-confirm"><span>I understand this will consume this single-use ticket and perform exactly one internal read-only call. No external writes, capital movement, trading, outreach, purchases, or credential changes are permitted.</span></label><button id="run-button" class="run-button">Consume ticket and run one read-only call</button><div id="run-status" class="run-status"></div>`;const btn=box.querySelector('#run-button');btn.onclick=async()=>{const status=box.querySelector('#run-status');status.textContent='';status.className='run-status';if(!box.querySelector('#run-confirm').checked){status.textContent='Explicit single-use read-only confirmation is required.';status.className='run-status err';return}btn.disabled=true;try{const csrf=await loadConsoleCsrf();const rr=await fetch('/operator/api/dispatch-tickets/'+encodeURIComponent(d.dispatch_ticket_id)+'/run-read-only',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify({confirm_single_use_read_only:true})});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Read-only run rejected')}const x=await rr.json();const e=x.receipt;status.innerHTML=`<div class="receipt-box"><strong>${esc(e.status)}</strong><br>Receipt: ${esc(e.execution_receipt_id)}<br>Operation: ${esc(e.operation)} · HTTP: ${esc(e.http_status??'n/a')}<br>Result SHA-256: ${esc(e.result_sha256)}<br>Execution receipt SHA-256: ${esc(e.execution_receipt_sha256)}<br>Raw result exposed in console: no<br>Evidence return created automatically: no</div>`;status.className='run-status ok';setTimeout(()=>loadCase(recordId),500)}catch(err){status.textContent=String(err.message||err);status.className='run-status err'}finally{btn.disabled=false}}}catch(err){box.innerHTML=`<h3>Execute One Read-Only Call</h3><div class="muted">${esc(err.message||'Unavailable.')}</div>`}}
const _v38LoadCase=loadCase;loadCase=async function(id){await _v38LoadCase(id);await loadRunnerControl(id)};setTimeout(()=>{if(selected)loadRunnerControl(selected)},1800);
</script>
"""

CONSOLE_HTML_V39 = CONSOLE_HTML_V38.replace("</body>", RUNNER_CONTROL_SCRIPT + "</body>")
